mapper.select:
select s.*, c.name as clazzName
from tlias.student s
left join tlias.clazz c on s.clazz_id = c.id


    and s.name like concat('%', #{name}, '%')


        and s.gender = #{degree}


        and s.clazz_id = #{clazzId}
